#include "membership_office_transition.hpp"
#include "organization_internal.hpp"
#include "organization_fact_source.hpp"
#include <algorithm>
namespace hanmo::resident {namespace {
struct Failure{RuleError error;};
[[noreturn]]void fail(const char* code,const StableId& id){throw Failure{common_failure(code,id).error};}
template<class T>T take(Outcome<T> value){if(!value.ok)throw Failure{std::move(value.error)};return std::move(value.value);}
void take(Status value){if(!value.ok)throw Failure{std::move(value.error)};}
const OrganizationFact& fact(const CommonStore& c,const OrganizationState& s,const StableId& id,const char* kind){const auto* f=s.facts.find(id);const auto* h=c.state().facts.find(id);if(!f||f->id!=id||f->kind!=kind||!h||h->id!=id||h->kind!=kind||h->domain!="organization")fail("MembershipOfficeOriginalFactRequired",id);return *f;}
void before(const CommonStore& c,const StableId& earlier,const StableId& later){const auto& order=c.state().facts.order();auto a=std::find(order.begin(),order.end(),earlier),b=std::find(order.begin(),order.end(),later);if(a==order.end()||b==order.end()||a>=b)fail("MembershipOfficeCauseOrder",later);}
const OrgMemberState& departure(const CommonStore& c,const OrganizationState& s,const OrganizationCatalog& catalog,const OrganizationFact& f){if(f.response!=MemberResponse::departed||f.actor_id.empty()||!f.office_id.empty()||!c.actor(f.actor_id))fail("MembershipActualDepartureRequired",f.id);const OrgMemberState* member=nullptr;for(const auto& row:s.members.rows())if(row.second.last_fact_id==f.id){if(member)fail("MembershipDepartureEpisodeAmbiguous",f.id);member=&row.second;}if(!member||member->response!=MemberResponse::departed||member->actor_id!=f.actor_id||member->organization_id!=f.organization_id||member->response_since_tick!=f.tick)fail("MembershipDepartureEpisodeRequired",f.id);const auto* policy=catalog.member_policies.find(member->policy_id);if(!policy||!policy->may_leave)fail("MembershipDeparturePermissionRequired",f.id);if(member->episode_source){const auto& e=*member->episode_source;if(e.departure_fact_id!=f.id||e.departed_tick!=std::optional<Integer>{f.tick})fail("MembershipDepartureOriginalEpisodeMismatch",f.id);before(c,e.joined_fact_id,f.id);}else if(!catalog.members.find(member->id))fail("MembershipDepartureOriginalSeedRequired",f.id);for(const auto& id:member->duty_ids){const auto* duty=s.duties.find(id);if(!duty||duty->actor_id!=f.actor_id||duty->organization_id!=f.organization_id||duty->active)fail("MembershipDepartureDutyNotReleased",id);}return *member;}
const OrganizationFact* existing(const OrganizationState& s,const StableId& departed,const StableId& office){const OrganizationFact* result=nullptr;for(const auto& row:s.facts.rows()){const auto& f=row.second;if(f.kind=="organization_office_resigned"&&f.office_id==office&&f.cause_fact_ids==std::vector<StableId>{departed}){if(result)fail("DuplicateMembershipOfficeResignation",departed);result=&f;}}return result;}
}
Outcome<VerifiedOfficeTransition> MembershipOfficeTransitionRead::read_office_transition(const SourceRef& ref,const ReadStamp& stamp)const{try{
 const auto now=take(read_organization_authority_now(common_,&clock_));if(take(compare_world_moments(now,stamp.span().to)))fail("MembershipOfficeTrustedClockRequired",ref.id);
 const auto& source=fact(common_,state_,ref.id,"organization_office_resigned");if(ref.domain!="organization"||ref.kind!=source.kind||source.cause_fact_ids.size()!=1||source.office_id.empty()||source.office_change_payload||source.grant_change_payload||source.amount!=0||!source.code.empty()||!source.activity_id.empty()||source.response!=MemberResponse::serving)fail("MembershipOfficeResignationSourceInvalid",ref.id);
 const auto& departed=fact(common_,state_,source.cause_fact_ids.front(),"organization_member_response");departure(common_,state_,catalog_,departed);before(common_,departed.id,source.id);if(source.actor_id!=departed.actor_id||source.organization_id!=departed.organization_id||source.tick!=departed.tick||existing(state_,departed.id,source.office_id)!=&source)fail("MembershipOfficeDepartureMismatch",ref.id);
 const auto* t=sources_.find(ref.id);if(!t||!same_source_ref(t->source,ref)||t->kind!=OfficeTransitionKind::resign||t->organization_id!=source.organization_id||t->office_id!=source.office_id||t->old_holder!=std::optional<StableId>{source.actor_id}||t->new_holder||t->effective_moment.half_day_tick!=source.tick||take(compare_world_moments(t->effective_moment,now))>0)fail("MembershipOfficeTransitionMismatch",ref.id);
 if(catalog_.exact_fact_clock_enabled&&(!source.occurred_at||!departed.occurred_at||take(compare_world_moments(*source.occurred_at,t->effective_moment))||take(compare_world_moments(*departed.occurred_at,t->effective_moment))))fail("MembershipOfficeExactMomentMismatch",ref.id);
 const auto old=take(read_office_term_before_fact_at(common_,state_,catalog_,catalog_.authority_catalog_identity,t->office_id,t->effective_moment,departed.id,clock_));const auto at=take(read_office_term_before_fact_at(common_,state_,catalog_,catalog_.authority_catalog_identity,t->office_id,t->effective_moment,source.id,clock_));if(old.organization_id!=t->organization_id||old.epoch!=t->expected_epoch||old.holder_actor_id!=t->old_holder||at.epoch!=old.epoch||at.holder_actor_id!=old.holder_actor_id)fail("MembershipOfficeHistoricalTermMismatch",ref.id);
 return {true,*t,{}};
 }catch(Failure& e){return {false,{},std::move(e.error)};}}
Outcome<OrganizationEffects> consume_departed_membership_offices_in_candidate(CommonStore& common,OrganizationState& state,const OrganizationCatalog& catalog,const ActivityRead& activity,const MembershipReleaseRead& release,const StableId& id,const MembershipOfficeTransitionWriteContext& x){try{
 if(!catalog.authority_lifecycle_enabled)fail("OfficeLifecycleCapabilityRequired",id);const auto now=take(read_organization_authority_now(common,&x.clock));if(take(compare_world_moments(now,x.stamp.span().to)))fail("MembershipOfficeTrustedClockRequired",id);const auto& departed=fact(common,state,id,"organization_member_response");departure(common,state,catalog,departed);
 // An already adopted departure replays its original per-office terms, never today's new term.
 std::optional<WorldMoment> applied;for(const auto& row:state.facts.rows())if(row.second.kind=="organization_office_resigned"&&row.second.cause_fact_ids==std::vector<StableId>{id}){const auto* t=x.sources.find(row.first);if(!t)fail("MembershipOfficeTransitionRequired",row.first);if(applied&&take(compare_world_moments(*applied,t->effective_moment)))fail("MembershipDepartureMomentMismatch",id);applied=t->effective_moment;}
 const auto at=applied?*applied:now;const StableId departed_actor=departed.actor_id,departed_org=departed.organization_id;if(catalog.exact_fact_clock_enabled&&(!departed.occurred_at||take(compare_world_moments(*departed.occurred_at,at))))fail("MembershipDepartureExactMomentRequired",id);if(departed.tick!=at.half_day_tick)fail("MembershipDepartureActualMomentRequired",id);
 if(!applied){auto ready=take(release.membership_release_view(departed.actor_id));if(ready.actor_id!=departed.actor_id||ready.tick!=now.half_day_tick||ready.revision!=common.revision()||!ready.blockers.empty()||organization_detail::personally_committed(common,state,&activity,departed.actor_id))fail("MembershipDepartureResponsibilitiesRemain",id);}
 MembershipOfficeTransitionRead reader(common,state,catalog,x.sources,x.clock);OrganizationEffects effects;
 for(const auto& row:state.offices.rows()){const auto& office=row.second;auto original=take(read_office_term_before_fact_at(common,state,catalog,catalog.authority_catalog_identity,office.id,at,id,x.clock));if(original.organization_id!=departed_org||original.holder_actor_id!=std::optional<StableId>{departed_actor})continue;
  const auto* prior=existing(state,id,office.id);StableId resignation;
  if(prior)resignation=prior->id;else{if(applied)fail("MembershipDepartureOfficeCoverageMissing",office.id);if(office.epoch!=original.epoch||office.holder_actor_id!=original.holder_actor_id)fail("MembershipDepartureCannotClearLaterTerm",office.id);OrganizationFact source;source.kind="organization_office_resigned";source.organization_id=departed_org;source.actor_id=departed_actor;source.office_id=office.id;source.tick=at.half_day_tick;if(catalog.exact_fact_clock_enabled)source.occurred_at=at;source.cause_fact_ids={id};resignation=take(append_organization_fact_in_candidate(common,state,std::move(source)));VerifiedOfficeTransition transition;transition.source={"organization","organization_office_resigned",resignation};transition.organization_id=departed_org;transition.office_id=office.id;transition.expected_epoch=original.epoch;transition.old_holder=departed_actor;transition.kind=OfficeTransitionKind::resign;transition.effective_moment=at;if(!x.sources.insert(resignation,std::move(transition)))fail("DuplicateOfficeTransitionSource",resignation);}
  auto result=take(consume_office_transition(common,state,catalog,{"organization","organization_office_resigned",resignation},x.stamp,reader));if(!result.fact_id)fail("MembershipOfficeResultRequired",resignation);effects.fact_ids.push_back(resignation);effects.fact_ids.push_back(*result.fact_id);effects.receipt_ids.push_back(resignation);effects.receipt_ids.push_back(*result.fact_id);
 }
 return {true,std::move(effects),{}};
 }catch(Failure& e){return {false,{},std::move(e.error)};}}
Status validate_membership_office_transitions(const CommonStore& c,const OrganizationState& state,const OrganizationCatalog& catalog,const OrderedTable<VerifiedOfficeTransition>& sources,const OrganizationAuthorityClock& clock,const ReadStamp& stamp){try{
 MembershipOfficeTransitionRead reader(c,state,catalog,sources,clock);
 for(const auto& row:state.facts.rows())if(row.second.kind=="organization_office_resigned"){const auto t=take(reader.read_office_transition({"organization",row.second.kind,row.first},stamp));std::size_t count=0;for(const auto& f:state.facts.rows())if(f.second.office_change_payload)if(const auto* by=std::get_if<ByOfficeTransition>(&f.second.office_change_payload->cause);by&&same_source_ref(by->transition_source_ref,t.source)){const auto& p=*f.second.office_change_payload;if(f.second.office_id!=t.office_id||p.before_epoch!=t.expected_epoch||p.old_holder!=t.old_holder||p.new_holder||take(compare_world_moments(p.effective_moment,t.effective_moment)))fail("MembershipOfficeResultMismatch",row.first);before(c,row.first,f.first);++count;}if(count!=1)fail("MembershipOfficeResultCoverage",row.first);}
 for(const auto& row:sources.rows())if(row.second.source.kind=="organization_office_resigned"){if(row.first!=row.second.source.id)fail("MembershipOfficeSourceKeyMismatch",row.first);take(reader.read_office_transition(row.second.source,stamp));}
 // All offices held immediately before the actual departure must be represented once.
 for(const auto& row:state.facts.rows())if(row.second.kind=="organization_member_response"&&row.second.response==MemberResponse::departed){departure(c,state,catalog,row.second);const VerifiedOfficeTransition* timing=nullptr;for(const auto& source:state.facts.rows())if(source.second.kind=="organization_office_resigned"&&source.second.cause_fact_ids==std::vector<StableId>{row.first}){const auto* t=sources.find(source.first);if(!t)fail("MembershipOfficeTransitionRequired",source.first);if(timing&&take(compare_world_moments(timing->effective_moment,t->effective_moment)))fail("MembershipDepartureMomentMismatch",row.first);timing=t;}if(!timing){for(const auto& office:state.offices.rows()){auto current=take(read_current_office_term(c,state,catalog,catalog.authority_catalog_identity,office.first,&clock));const auto* initial=catalog.offices.find(office.first);if(!initial)fail("MembershipOfficeOriginalSeedRequired",office.first);auto holder=initial->holder_actor_id;for(const auto& head:c.state().facts.order()){if(head==row.first)break;const auto* changed=state.facts.find(head);if(changed&&changed->kind=="organization_office_changed"&&changed->office_id==office.first)holder=changed->actor_id.empty()?std::nullopt:std::optional<StableId>{changed->actor_id};}if(current.organization_id==row.second.organization_id&&holder==std::optional<StableId>{row.second.actor_id})fail("MembershipDepartureOfficeCoverageMissing",row.first);}continue;}for(const auto& office:state.offices.rows()){auto prior=take(read_office_term_before_fact_at(c,state,catalog,catalog.authority_catalog_identity,office.first,timing->effective_moment,row.first,clock));if(prior.organization_id==row.second.organization_id&&prior.holder_actor_id==std::optional<StableId>{row.second.actor_id}&&!existing(state,row.first,office.first))fail("MembershipDepartureOfficeCoverageMissing",row.first);}}
 return common_success();
 }catch(Failure& e){return {false,{},std::move(e.error)};}}
}
